xql_query:
// ============================================================
// Rule: WIN_VIP Account Disabled
// Vendor: Windows
// Objective:
// Detect activity associated with WIN_VIP Account Disabled.
// Severity: SEV_050_CRITICAL
// Category: OTHER
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0040 - Impact
// Technique: T1531 - Account Access Removal

// Fonte dos dados: eventos do Cortex XDR
dataset = xdr_data  

// Filtro que seleciona apenas eventos de log do Windows (EVENT_LOG)
// e especificamente aqueles com Event ID 4725 (desabilitação de conta de usuário)
| filter event_type = ENUM.EVENT_LOG AND action_evtlog_event_id = 4725  

// Criação de um campo para capturar o nome do usuário alvo (TargetUserName)
// O valor é extraído do JSON de detalhes do evento e limpo de aspas extras
| alter TargetUserName = trim(json_extract(action_evtlog_data_fields,"$.TargetUserName"),"\"")  

// Junção com o dataset de usuários VIP (vip_users)
// Permite verificar se a conta desabilitada pertence a um usuário crítico
| join type = inner conflict_strategy = both (
    dataset = vip_users
    | fields SAM
) as vip vip.SAM = TargetUserName  

// Campos selecionados para exibição no resultado final
| fields _time,                        // Data e hora do evento
         agent_hostname,               // Nome do host que registrou o evento
         TargetUserName,               // Conta de usuário desabilitada
         agent_ip_addresses,           // Endereço IP do host
         action_evtlog_message,        // Mensagem completa do evento
         action_evtlog_event_id        // ID do evento (4725)
